            <span className="phone-frame"><span className="phone-island"/><span className="phone-screen"><span className="phone-screen-top"><i/> SERIESBIO <small>01:28</small></span><span className="phone-pixel-art">{pixels.map(([x,y],i)=><i key={`${x}-${y}`} style={{left:`${x}%`,top:`${y}%`,animationDelay:`${(i%9)*-.17}s`}}/>)}</span><b>{phoneAwake?'IN MOTION':'WIP'}</b><small>{phoneAwake?(language==='it'?'Un passo alla volta':language==='de'?'Schritt für Schritt':'One step at a time'):(language==='it'?'Si muove su richiesta':language==='de'?'Auf Anfrage in Bewegung':'Moves on request')}</small><span className="phone-progress"><i/></span></span><span className="phone-home"/></span>
